import type { TroubleCodeGuide } from "./trouble-code-data";

const gmManuals={label:"Chevrolet manuals and guides",url:"https://experience.gm.com/support/vehicle/manuals-guides",note:"Official Chevrolet model-year and VIN manual lookup"};
const gmInjector={label:"GM Bulletin 20-NA-098 — gasoline injector identification",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10176632-9999.pdf",note:"GM guidance for 2014–2020 gasoline V6/V8 applications with P0300-series and fuel-trim codes; stresses correct injector identification"};
const gmPurge={label:"GM Special Coverage N222369620 — EVAP purge valve",url:"https://static.nhtsa.gov/odi/tsbs/2022/MC-10214480-0001.pdf",note:"GM procedure naming P0496, P0442, P0455, P0171 and P0174 when diagnosis leads to purge-solenoid replacement; coverage remains VIN-specific"};
const gmP2135={label:"GM Bulletin 11-06-04-007C — P2135 reduced-power repair",url:"https://static.nhtsa.gov/odi/tsbs/2012/MC-10138192-9999.pdf",note:"GM procedure for covered 2008–2011 Silverado engine RPOs; says not to replace the complete throttle body automatically"};
const gmP0521={label:"GM Bulletin 24-NA-173 — P0521 and oil-pump relief valve",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11009029-0001.pdf",note:"GM information for covered 2019–2024 L84/L87 trucks; requires electrical/sensor diagnosis before oil-pump inspection"};
const gmP0016L3B={label:"GM PIP5921 — 2.7L L3B P0016 diagnostic tip",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10237639-9999.pdf",note:"GM guidance for 2019–2023 Silverado 1500 2.7L with noise/no-start and possible loose intake-cam actuator cover screws"};
const gmP0016Gen5={label:"GM PIP5554A — Gen-V V6/V8 timing alignment",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10154276-9999.pdf",note:"GM timing-installation guidance for covered 2014–2019 Silverado 4.3L, 5.3L and 6.2L engines after internal repair"};
const gmP1101Harness={label:"GM Bulletin 21-NA-149 — Silverado wiring and multi-DTC diagnosis",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10247527-0001.pdf",note:"GM bulletin covering selected Silverado engine-harness faults; P1101 appears among possible codes and is not by itself proof of harness failure"};

const silveradoVehicle={name:"Chevrolet Silverado",kicker:"CHEVROLET SILVERADO · GASOLINE ENGINE DIAGNOSTICS",breadcrumb:"Chevrolet Silverado",about:"Chevrolet Silverado gasoline-engine diagnostics",yearsIntro:"Silverado is a nameplate, not one diagnostic application. The 4.3L V6, 5.3L and 6.2L V8s, 2.7L turbo, earlier small-block generations and diesel engines use different sensors, fuel systems, timing drives and bulletins. Read the VIN, emissions label and RPO list before selecting service information."};

type Input=Omit<TroubleCodeGuide,"slug"|"vehicle"|"yearNotes"|"sources"|"deepDive"|"closing">&{slug:string;yearNotes:string[];sources?:TroubleCodeGuide["sources"];deepDive?:NonNullable<TroubleCodeGuide["deepDive"]>};
function page(x:Input):TroubleCodeGuide{return{...x,slug:`chevrolet/silverado/${x.slug}`,vehicle:silveradoVehicle,yearNotes:[...x.yearNotes,"Confirm Silverado 1500 versus 2500HD/3500HD, model year, engine RPO, emissions certification and calibration before using a bulletin or parts catalog.","Diesel Duramax engines are outside these gasoline diagnostic workflows unless a cited source explicitly includes that engine.","Aftermarket tunes, cylinder-deactivation changes, intakes, exhaust work and recent engine repairs alter the diagnostic baseline and must be disclosed."],deepDive:[...(x.deepDive??[]),{heading:`How to interpret a Silverado scan report for ${x.code}`,paragraphs:[`Save confirmed, pending and permanent codes plus the first freeze frame before clearing ${x.code}. RPM, load, coolant temperature, vehicle speed, fuel level and time since start identify whether the fault matured at cold start, idle, cruise, deceleration or load. That condition determines which test is valid.`,`Read companion codes as a system. A circuit or reference-voltage code moves electrical testing ahead of component replacement; active misfire must be resolved before catalyst conclusions; multiple unrelated codes can point to voltage, grounds or harness damage. Record readiness because clearing also erases monitor evidence.`,`Graph commanded and actual values together and label units. Compare bank-to-bank data on V6/V8 engines and compare cold temperature sensors with ambient. A normal warm-idle snapshot cannot disprove a fault that occurred during refueling, cylinder deactivation, boost or an overnight soak.`]},{heading:`DIY checks and professional boundaries`,paragraphs:["An owner can check cold fluid levels, battery terminals, intake/EVAP hoses, accessible grounds and connectors, air ducts and recent repair areas. A scan tool can preserve freeze frame and graph basic PIDs. Photograph everything before disturbing parts so the original evidence remains useful.","Use a professional for direct-injection pressure work, bidirectional throttle/purge tests, regulated EVAP smoke, oscilloscope correlation, mechanical oil-pressure measurement, compression/leak-down or catalyst testing. High-pressure fuel, hot exhaust and internal timing work are not safe trial-and-error jobs.","Ask which test failed and which RPO-specific procedure was used. A diagnosis written only as 'code present—replace part' does not separate a component from its wiring, plumbing, calibration or the condition that damaged it."]},{heading:`Application of GM bulletins`,paragraphs:["A bulletin describes a known condition on a defined population; it is not a recall and not proof that the named fault exists on every truck. Match model, year, engine RPO, build breakpoint and symptoms before using it.","Follow strategy-based diagnosis first unless the document directs otherwise. Record VIN eligibility and calibration history. A similar code on an engine outside the bulletin requires the normal service-information path, not a copied repair.","When a bulletin warns against automatic replacement, preserve that warning in the estimate. Software, terminals, a serviceable sensor cover, oil pressure or mechanical inspection may be required before an assembly is condemned."]},{heading:`Verification after the repair`,paragraphs:[`Clear ${x.code} only after saving the original report and correcting a proven cause. Inspect all disturbed connectors, hoses, seals, fluid levels and fasteners before starting, then watch the relevant data at idle for an unsafe trend.`,`Repeat the safe part of the freeze-frame condition rather than settling for five minutes at idle. Check pending codes and confirm the monitored signal or counter behaves normally. Stop if oil pressure, temperature, misfire or fuel control becomes unsafe.`,`Allow readiness to progress without another reset. Permanent codes clear after sufficient passing monitor operation, not battery disconnection. Keep before-and-after scan reports as evidence that the monitored condition—not merely the lamp—returned to normal.`]}],closing:{title:`What closes a ${x.code} diagnosis`,paragraphs:[`A successful repair reproduces the original operating condition safely, shows normal relevant data and produces no returning pending ${x.code} or companion fault. If the original condition cannot be reproduced, document that limitation rather than claiming certainty.`,`Reinspect for leaks, loose connectors, chafing and fluid changes after the verification drive. When fuel, oil pressure, timing or catalyst damage was involved, follow the service procedure's additional inspection plan.`,`If the code returns, compare the new freeze frame with the first one before clearing. An identical pattern suggests incomplete root-cause correction; a changed load, temperature or companion-code pattern can indicate a second fault.`]},sources:[...(x.sources??[]),gmManuals]};}

export const troubleCodeSilverado: TroubleCodeGuide[]=[
page({slug:"p0300",code:"P0300",title:"P0300 Code Chevy Silverado: Misfire Causes and Diagnostic Tests",description:"Diagnose P0300 on a Chevy Silverado by engine and cylinder pattern. Test plugs, coils, injectors, fuel pressure, air leaks, compression and cam timing.",definition:"Engine Misfire Detected",severity:"Stop soon",driveAdvice:"Stop for a flashing lamp, severe shaking, raw-fuel odor, oil-pressure warning or mechanical noise. Active misfire can overheat the converters quickly. A steady lamp on a smooth-running truck may allow a short diagnostic trip, but do not tow or apply heavy load.",quickAnswer:"P0300 means the ECM detected crank-speed changes consistent with misfire across multiple cylinders or without enough consistency to assign one cylinder. It does not identify a coil. On a Silverado, first compare P0301–P0308 counters, banks, fuel trims and freeze frame; then separate one-cylinder ignition/injector/compression faults from system-wide air, fuel-pressure, timing or electrical problems.",symptoms:[{key:"flash",label:"Lamp flashes under load",response:"Release throttle and stop sustained driving; inspect the cylinders whose counters rise before repeating a damaging event."},{key:"idle",label:"Rough mainly at idle",response:"Compare bank trims at idle and higher airflow; smoke-test intake, PCV and brake-booster paths."},{key:"cold",label:"Cold-start-only misfire",response:"Save early counters and inspect injector leakage, plug deposits and mechanical sealing."},{key:"bank",label:"One bank dominates",response:"Focus on that bank's intake/exhaust sealing, injectors, harness and valve operation."},{key:"after",label:"Misfire began after injector or engine work",response:"Verify injector part/flow identification, connectors, grounds, timing and relearns before buying parts."}],causes:[{cause:"Worn/fouled plugs or weak coils",evidence:"Load-sensitive misfire or count follows a controlled swap",firstTest:"Compare plugs in order and move one known-good coil after identifying a leader"},{cause:"Injector delivery or wrong replacement injector",evidence:"Ignition checks pass; balance/leak result differs or repair history",firstTest:"Use RPO-specific injector test and GM catalog identification"},{cause:"Unmetered air or PCV leak",evidence:"Positive trims strongest at idle",firstTest:"Smoke-test the sealed intake"},{cause:"Fuel-pressure shortfall",evidence:"Both banks misfire/lean as demand rises",firstTest:"Graph commanded versus actual low/high pressure"},{cause:"Compression, lifter, valve or timing fault",evidence:"Misfire stays, relative compression low or noise/correlation codes",firstTest:"Run relative compression then mechanical tests"}],freezeFrame:["Cylinder counters","RPM/load/coolant temperature","Bank 1 and 2 fuel trims","Commanded/actual fuel pressure","Injector/coil/cam companion codes","Oil pressure and recent repair history"],steps:[{title:"Preserve the pattern",detail:"Save all codes, counters and freeze frame before clearing."},{title:"Identify cylinder versus system",detail:"Compare counts at idle and safe load plus bank trims."},{title:"Inspect first",detail:"Check ducts, grounds, connectors, PCV, oil and coolant."},{title:"Test ignition methodically",detail:"Read plugs and use one controlled coil swap."},{title:"Move to fuel and mechanical evidence",detail:"Test pressure, injector balance and compression when the fault stays."},{title:"Verify under the original condition",detail:"Confirm stable counts and no pending return."}],dontReplace:"Do not install eight coils or injectors for P0300. Random parts erase the pattern and can introduce incorrect injector flow classification. Prove the failed cylinder or system first.",deepDive:[{heading:"GM injector identification matters",paragraphs:["GM Bulletin 20-NA-098 warns that an incorrect injector installed during service can create rough idle, misfire and skewed trims on covered gasoline V6/V8 engines.","Order by VIN/RPO and the current parts catalog; physical fit alone does not establish the correct flow classification."]}],yearNotes:["2014–2020 Gen-V gasoline V6/V8 trucks use direct injection and engine-specific injector identification.","The 2.7L turbo adds charge-air and turbo control tests not used on a naturally aspirated V8."],faqs:[{question:"Can I drive with P0300?",answer:"Stop for flashing or severe symptoms; otherwise limit load until diagnosed."},{question:"Does P0300 mean bad coils?",answer:"No. Air, fuel, injector, compression and timing faults can create it."},{question:"How do I find the cylinder?",answer:"Use misfire counters, Mode $06 and pending P0301–P0308 codes under freeze-frame conditions."},{question:"Can a lifter cause it?",answer:"Yes, valve-lift or compression loss can produce a fixed-cylinder misfire."},{question:"Can low fuel pressure cause multiple misfires?",answer:"Yes, especially when counts and lean correction rise with load."},{question:"Should I clear it first?",answer:"No; save freeze frame and counters first."},{question:"Can the wrong injector cause P0300?",answer:"Yes. GM documents incorrect injector identification as a cause of roughness and trim/misfire codes."},{question:"What proves repair?",answer:"Stable counters and no pending fault under the original setting condition."}],sources:[gmInjector]}),
page({slug:"p0171",code:"P0171",title:"P0171 Code Chevy Silverado: Bank 1 Lean Diagnosis",description:"Diagnose Silverado P0171 with bank-to-bank fuel trims, smoke testing, purge checks, exhaust inspection and commanded-versus-actual fuel pressure.",definition:"Fuel Trim System Lean Bank 1",severity:"Diagnose promptly",driveAdvice:"Avoid towing and heavy acceleration until mixture control is verified. Stop for flashing misfire, sharp power loss, knock or overheating. A steady lamp may permit a short diagnostic trip when the engine remains smooth.",quickAnswer:"P0171 means Bank 1 required more positive fuel correction than the ECM allows. On a Silverado V6/V8, Bank 1 is the cylinder bank containing cylinder 1; confirm its physical side from the exact engine diagram. Compare Bank 1 with Bank 2: one-bank lean behavior favors a local intake/exhaust/injector fault, while both banks lean raises common air, purge or fuel-supply causes.",symptoms:[{key:"idle",label:"Trim strongest at idle",response:"Smoke-test intake, PCV and brake-booster plumbing."},{key:"load",label:"Trim worsens with load",response:"Graph commanded/actual pressure and measured airflow."},{key:"one",label:"Only Bank 1 is lean",response:"Inspect Bank 1 runners, pre-sensor exhaust sealing and injectors."},{key:"both",label:"P0171 and P0174",response:"Prioritize common intake, purge, airflow or fuel supply."},{key:"refuel",label:"Rough after refueling",response:"Test purge flow when commanded closed."}],causes:[{cause:"Bank 1 intake/PCV leak",evidence:"Bank difference and idle-sensitive correction",firstTest:"Smoke-test runners and seals"},{cause:"Purge valve leaking",evidence:"Post-refuel symptom or flow when closed",firstTest:"Command closed and verify sealing"},{cause:"Fuel-pressure/injector shortfall",evidence:"Correction rises with demand",firstTest:"Graph pressure and run balance test"},{cause:"Bank 1 exhaust leak",evidence:"Cold tick/soot ahead of upstream sensor",firstTest:"Inspect cold and smoke safely"},{cause:"Biased airflow or upstream sensor",evidence:"PID fails plausibility/controlled response",firstTest:"Prove response after physical faults are excluded"}],freezeFrame:["Both-bank trims","RPM/load","Coolant/closed-loop state","MAF/MAP","Fuel pressure command/actual","Purge and companion codes"],steps:[{title:"Confirm bank pattern",detail:"Save freeze frame and compare both banks."},{title:"Compare idle and airflow",detail:"Record trims at idle and 2,500 rpm."},{title:"Smoke-test",detail:"Inspect intake and PCV without flammable spray."},{title:"Test purge",detail:"Verify no unintended flow."},{title:"Verify fuel/exhaust/sensors",detail:"Use pressure and controlled response tests."},{title:"Recheck both banks",detail:"Repeat original load and inspect pending codes."}],dontReplace:"Do not replace Bank 1 oxygen sensor because it reports lean. It is often the messenger. Prove sensor bias only after air, purge, exhaust and fuel delivery pass.",deepDive:[{heading:"Purge coverage can include P0171",paragraphs:["GM Special Coverage N222369620 names P0171 among codes that may lead SI diagnosis to purge-solenoid replacement.","Coverage and the failed test remain VIN-specific; the document does not make every P0171 a purge valve."]}],yearNotes:["Cylinder-bank orientation and fuel-pressure architecture change by engine RPO.","2024 L8T HD bulletin 24-NA-042 is a separate application involving Bank 1 sensor harness routing; do not apply it broadly."],faqs:[{question:"What does P0171 mean?",answer:"Bank 1 fuel correction exceeded its lean limit."},{question:"Which side is Bank 1?",answer:"It is the bank containing cylinder 1; verify the exact engine diagram."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when trim is highest at idle."},{question:"Can purge cause it?",answer:"Yes if the valve flows closed, and GM coverage names the code on defined vehicles."},{question:"Does it mean a bad O2 sensor?",answer:"No; test the reported condition first."},{question:"Can I tow with P0171?",answer:"Avoid towing until fuel supply and mixture are verified."},{question:"What scan data matters?",answer:"Both-bank trims at idle/load plus pressure, airflow and purge."},{question:"How is repair confirmed?",answer:"Normal trims and no pending lean/misfire under the original condition."}],sources:[gmPurge,gmInjector]}),
page({slug:"p0420",code:"P0420",title:"P0420 Code Chevy Silverado: Catalyst Diagnosis Before Replacement",description:"Test Silverado P0420 correctly: repair misfire and fuel-trim faults, inspect exhaust leaks, verify oxygen-sensor response and match the emissions-certified converter.",definition:"Catalyst System Low Efficiency Bank 1",severity:"Service soon",driveAdvice:"A steady P0420 alone often permits short-term driving, but stop for a flashing lamp, severe power loss, glowing converter, overheating or raw-fuel odor. Repair active misfire or mixture faults before extended driving.",quickAnswer:"P0420 means the ECM judged Bank 1 catalyst oxygen-storage performance below threshold. It does not prove the converter is the first failed part. Misfire, rich/lean control, oil or coolant entry, exhaust leakage, sensor/circuit error and an incorrect replacement converter must be resolved before the catalyst monitor is trusted.",symptoms:[{key:"alone",label:"Only P0420",response:"Inspect leaks and run the GM catalyst test under enabling conditions."},{key:"misfire",label:"Misfire accompanies it",response:"Repair misfire before judging the converter."},{key:"rattle",label:"Rattle or restriction",response:"Stop heavy load and test substrate/backpressure."},{key:"fuel",label:"Abnormal trims or fuel odor",response:"Correct mixture/purge/injector faults first."},{key:"return",label:"Returned after replacement",response:"Verify part certification, sensors, leaks and original root cause."}],causes:[{cause:"Aged/damaged catalyst",evidence:"Monitor fails after upstream faults excluded",firstTest:"Run GM catalyst diagnosis"},{cause:"Misfire or mixture fault",evidence:"Companion codes/counters/trims",firstTest:"Repair and verify upstream fault"},{cause:"Exhaust leak",evidence:"Tick, soot or smoke leak",firstTest:"Inspect and low-pressure smoke"},{cause:"Sensor/wiring error",evidence:"Response or circuit fails testing",firstTest:"Test before replacement"},{cause:"Oil/coolant contamination or wrong converter",evidence:"Consumption history or application mismatch",firstTest:"Correct source and verify VIN emissions part"}],freezeFrame:["RPM/load/temp","Both-bank trims","O2/lambda signals","Misfire counters","Exhaust/repair history","Readiness and companion codes"],steps:[{title:"Save all codes",detail:"Preserve upstream evidence."},{title:"Repair misfire/mixture",detail:"Do not evaluate catalyst through an active fault."},{title:"Inspect exhaust",detail:"Check manifolds, flanges and sensor ports."},{title:"Prove sensor response",detail:"Use controlled tests and wiring checks."},{title:"Run monitor diagnosis",detail:"Follow engine/calibration enabling conditions."},{title:"Match replacement",detail:"Use VIN and emissions certification and verify readiness."}],dontReplace:"Do not buy a converter from P0420 alone. An upstream fault can destroy the replacement or an exhaust/sensor problem can leave the code unchanged.",deepDive:[{heading:"Bank 1 is application-specific",paragraphs:["V6/V8 engines have two catalyst banks. Confirm cylinder 1 and exhaust routing from the RPO-specific service view before replacing a bank assembly.","The 2.7L inline engine uses a different layout and cannot inherit a V8 bank diagram."]}],yearNotes:["Federal and California-emissions converters may use different certified part numbers.","Cylinder-deactivation and direct-injection faults can damage catalysts without making the catalyst the original cause."],faqs:[{question:"Does P0420 always mean a bad converter?",answer:"No. Upstream and measurement faults must be excluded."},{question:"Can misfire damage it?",answer:"Yes, unburned fuel can overheat the substrate."},{question:"Can I drive?",answer:"Usually briefly if alone and steady; stop for severe symptoms."},{question:"Should sensors be replaced first?",answer:"Only if circuit/response tests fail."},{question:"Can an exhaust leak set it?",answer:"Yes, especially near sensors or catalyst."},{question:"Why did it return?",answer:"Root cause, leak, sensor, calibration or wrong part may remain."},{question:"Will clearing pass inspection?",answer:"No; clearing resets readiness and permanent codes need passing operation."},{question:"What should a shop show?",answer:"Upstream-code status, exhaust integrity, sensor evidence and completed monitor."}]}),
page({slug:"p0016",code:"P0016",title:"P0016 Code Chevy Silverado: Cam and Crank Correlation Tests",description:"Diagnose Silverado P0016 by engine RPO. Check oil/VVT, cam and crank signals, mechanical timing, reluctor position and GM engine-specific bulletins.",definition:"Crankshaft Position–Camshaft Position Correlation Bank 1 Sensor A",severity:"Stop soon",driveAdvice:"Minimize driving and stop for timing noise, no-start, low oil pressure, stalling or a flashing lamp. A true mechanical timing or reluctor fault can worsen; do not perform high-rpm tests before integrity is established.",quickAnswer:"P0016 means the measured cam-to-crank relationship is outside the calibration window. It does not automatically mean the cam sensor failed. Oil/VVT control, wiring, reluctor position, timing installation and internal hardware all matter. GM publishes different diagnostic tips for 2.7L L3B trucks and Gen-V V6/V8 engines, so engine RPO is the first decision.",symptoms:[{key:"noise",label:"Noise or no-start on 2.7L",response:"Stop repeated cranking and inspect the intake-cam actuator/timing system under PIP5921 criteria."},{key:"after",label:"Appeared after engine work",response:"Verify base timing and relearn; PIP5554A addresses installation on covered Gen-V engines."},{key:"oil",label:"Low/wrong oil",response:"Correct and test pressure/VVT response without assuming service fixes mechanical timing."},{key:"hard",label:"Hard fault returns immediately",response:"Inspect waveform, wiring, reluctor and mechanical indexing."},{key:"multi",label:"Multiple timing codes",response:"Look for common oil, crank reference, base timing or harness faults."}],causes:[{cause:"Incorrect mechanical timing",evidence:"Recent work, repeatable offset or noise",firstTest:"Verify RPO-specific marks/tools"},{cause:"Reluctor moved/damaged",evidence:"Signals shifted with wiring/phaser passing",firstTest:"Inspect/index per applicable GM PI"},{cause:"Oil/VVT/phaser fault",evidence:"Desired and actual angles disagree",firstTest:"Verify oil pressure and actuator control"},{cause:"Cam/crank circuit fault",evidence:"Dropout or companion circuit code",firstTest:"Inspect and scope synchronized signals"},{cause:"2.7L intake actuator screw condition",evidence:"Covered L3B with front noise/debris/no compression",firstTest:"Apply PIP5921 criteria and inspect upper timing area"}],freezeFrame:["RPM/load","Desired/actual cam angle","Oil pressure/condition","Cam/crank companion codes","Cranking voltage","Engine RPO and repair history"],steps:[{title:"Identify engine",detail:"Read RPO before using any bulletin."},{title:"Check oil/noise",detail:"Do not repeatedly run a noisy engine."},{title:"Inspect circuits",detail:"Check voltage, grounds, pins and recent work."},{title:"Graph and scope",detail:"Compare commanded angle and synchronized signals."},{title:"Verify mechanics",detail:"Inspect timing/reluctor/actuator as evidence directs."},{title:"Relearn and verify",detail:"Complete GM procedure and repeat safe set condition."}],dontReplace:"Do not replace a cam sensor because P0016 names cam position. A new sensor cannot correct a moved reluctor, loose actuator hardware, oil-pressure fault or incorrect base timing.",deepDive:[{heading:"Two documented Silverado paths",paragraphs:["PIP5921 covers 2019–2023 Silverado 1500 2.7L L3B with possible loose intake-cam actuator cover screws, noise, debris or no compression.","PIP5554A addresses timing installation after internal repair on covered 2014–2019 4.3/5.3/6.2 Gen-V engines. Neither applies outside its stated engine/year symptoms."]}],yearNotes:["2012–2013 legacy V8 and 2014 4.3L bulletins also discuss moved crank reluctors on defined populations.","Timing marks, fasteners and relearns are not interchangeable among 2.7L, V6 and V8 engines."],faqs:[{question:"Is P0016 a bad cam sensor?",answer:"Not necessarily; it is a relationship fault."},{question:"Can oil cause it?",answer:"Oil affects VVT, but cannot repair mechanical misalignment."},{question:"Can I drive?",answer:"Minimize driving and stop for noise/no-start/low pressure."},{question:"What does Sensor A mean?",answer:"It identifies the monitored cam location; confirm engine-specific nomenclature."},{question:"Why after repair?",answer:"Base timing, connectors, triggers or relearn may be wrong."},{question:"Can a reluctor move?",answer:"GM has documented moved/damaged reluctor conditions on defined engines."},{question:"What is the 2.7L issue?",answer:"GM PIP5921 describes possible loose intake-cam actuator cover screws on covered trucks."},{question:"What proves repair?",answer:"Correct mechanical relationship, normal cam tracking, completed relearn and no pending return."}],sources:[gmP0016L3B,gmP0016Gen5]}),
page({slug:"p1101",code:"P1101",title:"P1101 Code Chevy Silverado: Intake Airflow Performance Diagnosis",description:"Diagnose Silverado P1101 by engine: inspect intake and charge pipes, MAF/MAP plausibility, throttle, PCV/crankcase pressure and wiring before replacing sensors.",definition:"Intake Air Flow System Performance",severity:"Diagnose promptly",driveAdvice:"A steady lamp with normal power may permit gentle diagnosis, but stop for reduced power, stalling, oil leakage, abnormal boost noise or multiple electrical warnings. Avoid towing and boost until intake plumbing and sensor plausibility are verified.",quickAnswer:"P1101 means the ECM's calculated airflow model disagrees with measured inputs; it is not automatically a MAF failure. Depending on Silverado engine, the comparison can involve MAF, MAP/boost, throttle angle, charge plumbing, PCV/crankcase flow and calibration. Multiple unrelated codes or blown fuses move harness/power inspection ahead of airflow parts.",symptoms:[{key:"power",label:"Reduced power",response:"Inspect charge/intake pipes and throttle plus companion boost codes."},{key:"multi",label:"Many codes or gauges sweep",response:"Check shared power, fuses and harness chafe before sensors."},{key:"oil",label:"Oil leak/crankcase pressure",response:"Test PCV restriction and crankcase pressure for the exact engine."},{key:"after",label:"After air-filter/intake work",response:"Check MAF direction, seals, ducts and disconnected hoses."},{key:"none",label:"Intermittent lamp only",response:"Use freeze frame and plausibility graphs under the setting load."}],causes:[{cause:"Intake/charge pipe leak or disconnection",evidence:"Boost/airflow codes, witness marks or hiss",firstTest:"Pressure/smoke inspect appropriate tract"},{cause:"MAF/MAP contamination or circuit",evidence:"Signal implausible/dropout",firstTest:"Inspect wiring and compare sensors"},{cause:"Throttle/air-model issue",evidence:"Command/actual disagreement",firstTest:"Graph throttle and airflow model"},{cause:"PCV/crankcase restriction",evidence:"Abnormal crankcase pressure/oil leaks",firstTest:"Measure pressure and inspect RPO-specific PCV"},{cause:"Harness/power fault",evidence:"Multiple codes/fuses/gauge symptoms",firstTest:"Apply voltage-drop and harness inspection"}],freezeFrame:["MAF/MAP/boost","Throttle command/actual","RPM/load","Fuel trims","Fuses/companion codes","Crankcase/oil leak history"],steps:[{title:"Identify engine",detail:"Select naturally aspirated versus 2.7 turbo path."},{title:"Inspect plumbing",detail:"Check filter-to-throttle and charge connections."},{title:"Check electrical pattern",detail:"Review fuses, shared references and harness movement."},{title:"Graph plausibility",detail:"Compare airflow, pressure and throttle together."},{title:"Test PCV/crankcase",detail:"Use engine-specific pressure method."},{title:"Verify under set load",detail:"Repeat freeze-frame condition safely."}],dontReplace:"Do not replace MAF, MAP and throttle body together. P1101 is a system plausibility result. Find the pipe, pressure, circuit or signal that disagrees.",deepDive:[{heading:"Why 21-NA-149 is a diagnostic boundary",paragraphs:["GM lists P1101 among many possible codes in selected Silverado wiring-harness conditions, particularly when multiple warnings, fuses or drivability symptoms occur.","One isolated P1101 does not prove harness chafe; use the bulletin only when engine, year and symptom pattern match."]}],yearNotes:["The 2.7L turbo uses charge-air and boost-sensor relationships absent on older naturally aspirated engines.","PCV layouts and airflow modeling change by engine RPO."],faqs:[{question:"Does P1101 mean a bad MAF?",answer:"No. It means airflow inputs/model disagree."},{question:"Can an intake leak cause it?",answer:"Yes, including charge-pipe faults on turbo engines."},{question:"Can PCV cause it?",answer:"Yes when crankcase flow/pressure is abnormal."},{question:"Can I drive?",answer:"Only gently if power is normal; stop for reduced power or multiple warnings."},{question:"Why many codes?",answer:"Shared power, fuses, grounds or harness damage may affect multiple circuits."},{question:"Should I clean the MAF?",answer:"Only with approved method after inspection; cleaning is not proof of repair."},{question:"What data matters?",answer:"MAF, MAP/boost, throttle, trims and load together."},{question:"What proves repair?",answer:"Plausible correlated signals and no pending return under original load."}],sources:[gmP1101Harness]}),
page({slug:"p0496",code:"P0496",title:"P0496 Code Chevy Silverado: EVAP Flow During Non-Purge",description:"Diagnose Silverado P0496 with post-refuel symptoms, purge-valve sealing, fuel-tank pressure, canister inspection and GM VIN-specific coverage checks.",definition:"Evaporative Emission System Flow During Non-Purge",severity:"Diagnose promptly",driveAdvice:"Usually not an immediate stop by itself, but limit driving for hard starting, stalling, raw-fuel odor or severe rich/lean running. Work in ventilation and keep ignition sources away from fuel vapor.",quickAnswer:"P0496 means the ECM detected EVAP flow when purge should not occur. A purge solenoid that leaks open is common, but hose routing, canister saturation, fuel-tank-pressure sensing and electrical command must be tested. GM special coverage N222369620 names P0496 among codes that may lead SI diagnosis to purge-solenoid replacement; coverage and diagnosis are VIN-specific.",symptoms:[{key:"refuel",label:"Hard start after refueling",response:"Test purge sealing before replacing unrelated ignition parts."},{key:"idle",label:"Rough idle",response:"Compare trims and isolate unintended vapor flow safely."},{key:"smell",label:"Fuel odor",response:"Inspect for liquid/vapor leak and canister saturation."},{key:"cap",label:"Code returns after cap",response:"P0496 concerns flow, not simply cap sealing."},{key:"none",label:"No symptom",response:"Use command and FTP response to catch intermittent leakage."}],causes:[{cause:"Purge solenoid leaking open",evidence:"Vacuum/flow with command off",firstTest:"Command closed and verify seal"},{cause:"Electrical command/circuit fault",evidence:"Valve energized unexpectedly or circuit code",firstTest:"Test command, voltage and control"},{cause:"Canister saturated with liquid fuel",evidence:"Topping-off history/fuel in vapor line",firstTest:"Inspect canister and lines"},{cause:"FTP sensor/circuit bias",evidence:"Implausible pressure response",firstTest:"Test controlled response/reference"},{cause:"Misrouted/damaged EVAP plumbing",evidence:"Recent repair or incorrect connections",firstTest:"Compare routing with RPO service diagram"}],freezeFrame:["Fuel level","FTP","Purge command","Trim","Time since refuel","EVAP companion codes"],steps:[{title:"Save data",detail:"Record fuel level/refuel history."},{title:"Check coverage",detail:"Confirm N222369620 by VIN."},{title:"Test valve closed",detail:"Verify no flow/vacuum."},{title:"Inspect canister/lines",detail:"Look for liquid fuel and damage."},{title:"Validate FTP/circuit",detail:"Use controlled response."},{title:"Run EVAP monitor",detail:"Verify no pending return."}],dontReplace:"Do not replace the gas cap for a flow-during-non-purge code without testing purge. The cap seals the system; it does not command manifold vapor flow.",deepDive:[{heading:"What special coverage does and does not prove",paragraphs:["N222369620 provides additional purge-valve coverage for defined vehicles and names P0496 among possible codes.","SI diagnosis must still lead to purge replacement; the document explicitly says no replacement under the program when diagnosis does not."]}],yearNotes:["EVAP layouts and coverage differ by year, tank and engine.","Stop topping off after the nozzle clicks; liquid fuel can damage the canister."],faqs:[{question:"What does P0496 mean?",answer:"EVAP flow was detected when purge should be off."},{question:"Is it usually purge valve?",answer:"Often, but it must fail a sealing/command test."},{question:"Can gas cap cause it?",answer:"A cap is not the primary flow-control component."},{question:"Why after refueling?",answer:"A leaking purge valve can pull excessive vapor into the intake."},{question:"Can I drive?",answer:"Usually briefly if mild; stop for stalling or strong fuel symptoms."},{question:"Is there GM coverage?",answer:"N222369620 covers defined VINs when diagnosis leads to purge replacement."},{question:"Can topping off matter?",answer:"Yes, it can saturate the canister."},{question:"What confirms repair?",answer:"No flow when purge is closed and passing EVAP operation."}],sources:[gmPurge]}),
page({slug:"p0521",code:"P0521",title:"P0521 Code Chevy Silverado: Oil Pressure Performance Tests",description:"Treat Silverado P0521 as an oil-pressure problem until proven otherwise. Verify level, mechanical pressure, sensor circuit and applicable GM oil-pump guidance.",definition:"Engine Oil Pressure Sensor Performance",severity:"Stop soon",driveAdvice:"Stop the engine for a low-oil-pressure warning, valvetrain/knock noise or pressure near zero. Check level only after parking safely and allowing drain-back. Do not keep driving to see whether the reading returns; genuine low pressure can destroy bearings quickly.",quickAnswer:"P0521 means the oil-pressure signal is outside the ECM's expected performance, not automatically that the sensor failed. Confirm oil level/specification and leaks, then compare scan/gauge information with a mechanical pressure test and inspect the circuit. GM Bulletin 24-NA-173 documents a stuck oil-pump relief valve on covered 2019–2024 L84/L87 vehicles and explicitly requires electrical/sensor diagnosis before oil-pump inspection.",symptoms:[{key:"zero",label:"Low/zero pressure and noise",response:"Shut down immediately and tow for mechanical testing."},{key:"idle",label:"Pressure low mainly hot idle",response:"Measure mechanically; covered L84/L87 trucks may require relief-valve/pump investigation."},{key:"jump",label:"Gauge jumps implausibly",response:"Inspect sensor, connector, wiring and reference/ground."},{key:"after",label:"After oil service",response:"Verify level, viscosity, filter and drain/filter sealing."},{key:"repeat",label:"Sensor already replaced",response:"Do not repeat the part; bulletin notes repeat visits and directs full flowchart."}],causes:[{cause:"Actual low oil pressure",evidence:"Mechanical gauge confirms low",firstTest:"Stop engine and follow lubrication diagnosis"},{cause:"Stuck oil-pump relief valve",evidence:"Covered L84/L87, low hot-idle pressure after electrical checks",firstTest:"Apply 24-NA-173 flow"},{cause:"Sensor or screen/circuit fault",evidence:"Mechanical pressure normal but signal wrong",firstTest:"Test sensor/circuit response"},{cause:"Wrong oil/level/filter or aeration",evidence:"Service history/foam/incorrect level",firstTest:"Verify exact oil and filter"},{cause:"Bearing/internal wear",evidence:"Low pressure/noise/debris",firstTest:"Inspect oil/filter and mechanical condition"}],freezeFrame:["Oil-pressure PID","RPM/temp/load","Oil level/spec/filter","Voltage","Noise/debris","Engine RPO and prior sensor history"],steps:[{title:"Stop if pressure unsafe",detail:"Do not collect road data with noise/low warning."},{title:"Verify oil service basics",detail:"Check cold/level/spec/filter/leaks."},{title:"Inspect circuit",detail:"Check connector, wiring and reference."},{title:"Measure mechanically",detail:"Use RPO temperature/rpm specifications."},{title:"Apply bulletin by RPO",detail:"Use 24-NA-173 only on covered L84/L87."},{title:"Verify hot and loaded",detail:"Confirm stable pressure after repair."}],dontReplace:"Do not assume the oil-pressure sensor is harmlessly wrong. Prove mechanical pressure first when warning/noise exists. Replacing a sensor cannot restore pressure lost through a pump, relief valve or bearings.",deepDive:[{heading:"What GM 24-NA-173 adds",paragraphs:["The bulletin covers defined 2019–2024 5.3L L84 and 6.2L L87 applications and identifies a stuck oil-pump relief valve as a possible low-idle-pressure cause.","It also says to complete the P0521 diagnostic flowchart for electrical and sensor concerns before inspecting the pump."]}],yearNotes:["Older Silverado engines may use different sensor screens, pressure specifications and bulletins.","Engine RPO and oil temperature are mandatory when comparing measured pressure."],faqs:[{question:"Can I drive with P0521?",answer:"Not with a low-pressure warning or noise."},{question:"Is it always the sensor?",answer:"No; actual low pressure must be excluded."},{question:"Can wrong oil cause it?",answer:"Yes, level, viscosity, aeration and filter matter."},{question:"What is mechanical testing?",answer:"A calibrated gauge measures actual oil pressure at specified temperature/rpm."},{question:"Does GM document an oil-pump issue?",answer:"Yes on defined L84/L87 vehicles in 24-NA-173."},{question:"Why did it return after sensor replacement?",answer:"Circuit, pump relief, oil service or internal wear may remain."},{question:"Can low pressure damage the engine?",answer:"Yes, bearings and valvetrain can fail rapidly."},{question:"What proves repair?",answer:"Correct mechanical pressure and stable scan/gauge readings hot and under specified conditions."}],sources:[gmP0521]}),
page({slug:"p2135",code:"P2135",title:"P2135 Code Chevy Silverado: Throttle Sensor Correlation and Reduced Power",description:"Diagnose Silverado P2135 reduced-power complaints with TP1/TP2 graphs, connector and harness tests, throttle inspection and applicable GM programming guidance.",definition:"Throttle Position Sensor 1–2 Correlation",severity:"Diagnose promptly",driveAdvice:"Reduced Engine Power can limit throttle unexpectedly. Move out of traffic and avoid towing. Stop if throttle response is erratic, the engine stalls or several 5-volt-reference codes appear. Do not bypass the protection strategy.",quickAnswer:"P2135 means the two throttle-position signals no longer agree within the calibrated relationship. Causes include the throttle-position sensor assembly/cover on applicable older units, connector fretting, wiring/5-volt reference, throttle-body damage or calibration. GM Bulletin 11-06-04-007C covers defined 2008–2011 Silverado RPOs and specifically says not to replace the complete throttle body automatically.",symptoms:[{key:"reduced",label:"Reduced Engine Power",response:"Treat as a control-safety fault and diagnose before towing."},{key:"inter",label:"Intermittent over bumps",response:"Inspect connector pin fit and harness movement/chafe."},{key:"multi",label:"Other 5V codes",response:"Find shared reference short before throttle replacement."},{key:"dirty",label:"Throttle deposits",response:"Inspect plate/bore but do not force electronic throttle."},{key:"old",label:"2008–2011 covered RPO",response:"Check bulletin applicability and calibration procedure."}],causes:[{cause:"TP sensor assembly/cover fault",evidence:"Signals diverge with circuits sound",firstTest:"Graph TP1/TP2 and apply applicable bulletin"},{cause:"Connector/terminal fretting",evidence:"Dropout with wiggle/pin issue",firstTest:"Inspect tension/corrosion and voltage-drop"},{cause:"5V reference/ground fault",evidence:"Multiple sensor codes",firstTest:"Isolate shared circuit"},{cause:"Throttle body mechanical/electrical damage",evidence:"Binding/damage and failed commanded test",firstTest:"Inspect and run SI test"},{cause:"Calibration issue",evidence:"Covered repair requires ECM update",firstTest:"Verify latest VIN calibration"}],freezeFrame:["TP1/TP2","Pedal sensors","Commanded throttle","5V codes","Voltage","Reduced-power event conditions"],steps:[{title:"Save graphs/codes",detail:"Record both throttle signals."},{title:"Inspect connector/harness",detail:"Check pins, chafe and grounds."},{title:"Check shared reference",detail:"Isolate other 5V sensors."},{title:"Inspect throttle safely",detail:"Follow electronic throttle precautions."},{title:"Apply bulletin if covered",detail:"Use sensor cover/calibration path, not automatic body."},{title:"Verify full correlation",detail:"Command through safe range and road-test."}],dontReplace:"Do not replace the complete throttle body automatically on a covered older truck. GM's bulletin directs a defined sensor-cover and ECM-calibration repair after diagnosis. Later trucks require their own SI path.",deepDive:[{heading:"What 11-06-04-007C actually covers",paragraphs:["The bulletin applies to listed 2008–2011 Silverado engine RPOs with P2135 and Reduced Engine Power.","It warns against full throttle-body replacement and requires current ECM programming after the specified repair. It is not universal to every Silverado year."]}],yearNotes:["Electronic throttle assemblies and serviceability change by generation.","Multiple reference-voltage codes make shared wiring more likely than simultaneous sensor failures."],faqs:[{question:"What does P2135 mean?",answer:"TP sensor 1 and 2 no longer correlate."},{question:"Can I drive?",answer:"Avoid traffic/towing; reduced power can recur unpredictably."},{question:"Does it need a throttle body?",answer:"Not automatically; GM specifically warns against that on covered trucks."},{question:"Can wiring cause it?",answer:"Yes, especially intermittent or multi-code cases."},{question:"Can a 5V short cause it?",answer:"Yes, shared reference faults can distort several sensors."},{question:"Should I clean throttle first?",answer:"Inspection may help, but cleaning does not repair signal correlation."},{question:"Is there a bulletin?",answer:"11-06-04-007C covers defined 2008–2011 applications."},{question:"What confirms repair?",answer:"TP signals remain correlated without reduced power across commanded operation."}],sources:[gmP2135]}),
page({slug:"p0455",code:"P0455",title:"P0455 Code Chevy Silverado: Large EVAP Leak Diagnosis",description:"Diagnose Silverado P0455 large EVAP leak with cap/filler inspection, regulated smoke, purge and vent commands, canister checks and VIN-specific GM coverage.",definition:"Evaporative Emission System Large Leak Detected",severity:"Service soon",driveAdvice:"Usually drivable when it is the only code, but stop for liquid fuel leakage, strong vapor odor, stalling or severe post-refuel problems. Diagnose outdoors or with proper ventilation and avoid ignition sources.",quickAnswer:"P0455 means the EVAP system could not seal or hold the expected test pressure/vacuum, consistent with a large leak. A missing/incorrect cap, disconnected hose, stuck-open vent, purge leakage, cracked canister or tank/filler seal can cause it. GM special coverage N222369620 names P0455 when SI diagnosis may lead to purge-solenoid replacement, but that outcome is not automatic.",symptoms:[{key:"cap",label:"After refueling",response:"Inspect cap/filler and displaced hoses."},{key:"smell",label:"Strong vapor odor",response:"Inspect promptly for liquid/vapor leakage."},{key:"stall",label:"Hard start after refuel",response:"Test purge sealing."},{key:"no",label:"No symptoms",response:"Use regulated smoke and commanded valves."},{key:"repeat",label:"Returns after cap",response:"Test whole system rather than more caps."}],causes:[{cause:"Missing/loose/wrong cap or filler seal",evidence:"Visible sealing fault",firstTest:"Inspect/install correct component"},{cause:"Disconnected/cracked EVAP hose",evidence:"Smoke/visual opening",firstTest:"Regulated smoke test"},{cause:"Vent valve stuck open",evidence:"Fails command/seal",firstTest:"Command and circuit test"},{cause:"Purge valve leaks",evidence:"Flow when closed/post-refuel",firstTest:"Sealing test and coverage check"},{cause:"Canister/tank/pump-module seal",evidence:"Smoke or fuel damage",firstTest:"Inspect by tank configuration"}],freezeFrame:["Fuel level","FTP","Purge/vent command","Ambient/temp","Refuel history","Companion EVAP codes"],steps:[{title:"Save evidence",detail:"Record fuel and companion codes."},{title:"Inspect cap/filler",detail:"Check correct sealing."},{title:"Check obvious hoses",detail:"Look above tank/engine routing."},{title:"Smoke-test",detail:"Use regulated EVAP pressure."},{title:"Command valves",detail:"Test purge and vent sealing/circuits."},{title:"Verify monitor",detail:"Allow correct enable window."}],dontReplace:"Do not assume every P0455 is a gas cap. A large plumbing opening or valve that cannot seal is equally plausible, and GM coverage requires SI diagnosis before purge replacement.",deepDive:[{heading:"Large leak is a monitor description",paragraphs:["It does not tell you where the opening is or whether it is physically large. A valve held open can look like a major leak to the monitor.","Smoke-testing and valve commands localize the path without parts guessing."]}],yearNotes:["Tank, capless/conventional filler and vent placement change by chassis configuration.","Special coverage eligibility is VIN-specific and time/mileage limited."],faqs:[{question:"Can I drive with P0455?",answer:"Usually if alone, but not with liquid leak or strong fuel symptoms."},{question:"Is it always a gas cap?",answer:"No. Hoses, valves, canister and seals are common paths."},{question:"Can purge cause it?",answer:"Yes if it will not seal."},{question:"Is there GM coverage?",answer:"N222369620 covers defined VINs when SI diagnosis leads to purge replacement."},{question:"How is it found?",answer:"Visual inspection, regulated smoke and valve commands."},{question:"Can topping off matter?",answer:"Yes, it can saturate/damage the canister."},{question:"Why won't monitor run?",answer:"Fuel level/temperature/soak may be outside enable conditions."},{question:"What proves repair?",answer:"System seals and EVAP monitor completes without pending code."}],sources:[gmPurge]}),
page({slug:"p0442",code:"P0442",title:"P0442 Code Chevy Silverado: Small EVAP Leak Testing",description:"Find Silverado P0442 small EVAP leaks with cap and filler checks, low-pressure smoke, purge/vent testing, fuel-tank-pressure data and GM purge coverage boundaries.",definition:"Evaporative Emission System Small Leak Detected",severity:"Service soon",driveAdvice:"Normally safe for short-term driving if alone, but fuel odor, liquid leakage, stalling or post-refuel rich/lean symptoms require prompt inspection. Keep sparks and flames away from vapor-system work.",quickAnswer:"P0442 means the EVAP monitor detected leakage smaller than the P0455 threshold. The location is not encoded. Cap seal, tiny hose cracks, quick-connect seals, vent or purge leakage, canister damage and pump-module/filler seals all require testing. GM coverage N222369620 names P0442 among possible purge-related codes but still requires SI diagnosis to lead to the valve.",symptoms:[{key:"alone",label:"Lamp only",response:"Use low-pressure smoke and valve commands."},{key:"refuel",label:"After refueling",response:"Inspect cap/filler and purge behavior."},{key:"odor",label:"Vapor smell",response:"Inspect for actual leakage promptly."},{key:"return",label:"Intermittent return",response:"Check temperature/fuel enable and flex hoses."},{key:"with",label:"P0496/P0171 also present",response:"Test purge leakage and coverage."}],causes:[{cause:"Cap/filler seal",evidence:"Seal damage or cap disturbance",firstTest:"Inspect correct cap and neck"},{cause:"Small hose/connector leak",evidence:"Smoke at seam",firstTest:"Low-pressure smoke"},{cause:"Purge valve seepage",evidence:"Flow when closed",firstTest:"Seal test"},{cause:"Vent valve/filter contamination",evidence:"Incomplete seal",firstTest:"Command/circuit inspect"},{cause:"Canister/tank seal or FTP bias",evidence:"Smoke/implausible pressure",firstTest:"Inspect and controlled sensor test"}],freezeFrame:["Fuel level","FTP","Commands","Ambient/coolant","Refuel timing","Companion codes"],steps:[{title:"Do not clear",detail:"Save enable context."},{title:"Inspect cap/filler",detail:"Check sealing surfaces."},{title:"Review purge symptoms",detail:"Use coverage only when applicable."},{title:"Smoke at low pressure",detail:"Watch every connector/seam."},{title:"Command valves and FTP",detail:"Verify sealing and response."},{title:"Complete monitor",detail:"Recheck pending status."}],dontReplace:"Do not repeatedly replace the cap. A small leak often needs methodical smoke inspection, and purge seepage can be too small to notice without a sealing test.",deepDive:[{heading:"Why small leaks take time",paragraphs:["Temperature changes and hose movement can open a leak only intermittently. Record fuel level and ambient conditions when it sets.","A rushed high-pressure smoke test can damage EVAP components; use the service procedure's regulated pressure."]}],yearNotes:["EVAP monitor enable windows and hardware vary by model year.","Coverage is not a universal purge-valve diagnosis."],faqs:[{question:"Can I drive with P0442?",answer:"Usually if alone; inspect promptly for odor or liquid fuel."},{question:"Is it gas cap?",answer:"It can be, but many other small leak paths exist."},{question:"Can purge cause it?",answer:"Yes, small leakage when closed can fail the monitor."},{question:"How is it found?",answer:"Regulated smoke plus valve and FTP tests."},{question:"Why intermittent?",answer:"Temperature, fuel level and hose movement affect small leaks."},{question:"Is there coverage?",answer:"N222369620 covers defined VINs when diagnosis supports purge replacement."},{question:"Should I clear before inspection?",answer:"No, clearing erases useful enable context/readiness."},{question:"What confirms repair?",answer:"No measured leak and a completed EVAP monitor."}],sources:[gmPurge]}),
];
